Q: Built-in helper to parse User.Identity.Name into Domain\Username A: <p>This is better (<em>easier to use, no opportunity of <code>NullReferenceException</code> and conforms to MS coding guidelines about treating empty and null string equally</em>):</p>
<pre><code>public static class Extensions
{
    public static string GetDomain(this IIdentity identity)
    {
        string s = identity.Name;
        int stop = s.IndexOf(&quot;\\&quot;);
        return (stop &gt; -1) ?  s.Substring(0, stop) : string.Empty;
    }

    public static string GetLogin(this IIdentity identity)
    {
        string s = identity.Name;
        int stop = s.IndexOf(&quot;\\&quot;);
        return (stop &gt; -1) ? s.Substring(stop + 1, s.Length - stop - 1) : string.Empty;
    }
}
</code></pre>
<p>Usage:</p>
<pre><code>IIdentity id = HttpContext.Current.User.Identity;
id.GetLogin();
id.GetDomain();
</code></pre>
<p>This requires C# 3.0 compiler (or newer) and doesn't require 3.0 .Net for working after compilation.</p>

Q: How to center an element in the middle of the browser window? A: <p>If your div contents are dynamic (because this is a pop-up) and can change in size (because it's contents are not a fixed size) then you might want to add the following JavaScript to your code that populates the div to ensure it never pops off the top of the document (so the top of your div cannot be scrolled in to view - annoying if you have the &quot;button&quot; to close the pop up at the top). The div is marked as &quot;position: absolute&quot; in the CSS and has to be visible before the height of it can be determined hence:</p>
<pre><code>var d = document.getElementById('id_of_div_to_be_centred');
d.style.removeProperty('display'); // make it visible (so the &quot;clientHeight&quot; is not 0)
var t = ( (window.innerHeight - d.clientHeight) / 2 ) + window.scrollY;
if (t &gt; (document.body.clientHeight - d.clientHeight) )
    t = document.body.clientHeight - d.clientHeight; //try to keep off the bottom
if (t&lt;0) 
    t=0; // never off the top
d.style.top = t + 'px';
</code></pre>
<p>Doing it this way instead of using &quot;position: fixed&quot; means that the pop-up div will be scrollable if larger than the current window. I found using the &quot;transform&quot; CSS on some browsers messed up my translucent background :)</p>

Q: Change object type at runtime maintaining functionality A: <p>You could use interfaces this way:</p>
<pre><code>/// &lt;summary&gt;
/// All properties and methods common to ClassOne and ClassTwo
/// &lt;/summary&gt;
interface IClassCommon
{
    object OneProperty { get; set; }
}

/// &lt;summary&gt;
/// methods and properties of ClassOne only
/// &lt;/summary&gt;
interface IClassOne : IClassCommon
{
    object OneMethod();
}

/// &lt;summary&gt;
/// methods and properties of ClassTwo only
/// Note that ClassTwo is sealed and does not implement IClassTwo.
/// So you need a Wrapper
/// &lt;/summary&gt;
interface IClassTwo : IClassCommon
{
    object OneMethod(string parameter);
}

/// &lt;summary&gt;
/// Wrapper for one ClassTwo-Instance
/// &lt;/summary&gt;
class ClassOne : IClassOne, IClassTwo
{
    private readonly ClassTwo _instance;       

    public ClassOne(ClassTwo instance)
    {
        _instance = instance;
    }

    object IClassCommon.OneProperty { get =&gt; _instance.OneProperty; set =&gt; _instance.OneProperty = value; }

    object IClassOne.OneMethod()
    {
        // Logic here
        return new object();
    }

    object IClassTwo.OneMethod(string parameter)
    {
        return _instance.OneMethod(parameter);
    }
}

/// &lt;summary&gt;
/// Sealed Class
/// &lt;/summary&gt;
public sealed class ClassTwo 
{
    public object OneProperty { get; set; }

    public object OneMethod(string parameter)
    {
        // ...
        return &quot;some string:&quot; + parameter;
    }
}


    public static void main(String[] args)
    {
        // if you can create an instance of sealed class ClassTwo at this point...
        var myObject = new ClassOne(new ClassTwo()) as IClassOne;

        // Use its properties and methods
        Console.WriteLine(&quot;FirstObject.OneProperty value: &quot; + myObject.OneProperty);
        Console.WriteLine(&quot;FirstObject.OneMethod returned value: &quot; + myObject.OneMethod());

        // Now, for some reason, continue to use the
        // same object but with another type
        var myObject2 = myObject as IClassTwo;

        // Continue to use properties and methods but
        // this time calls were being made to SecondObject properties and Methods           
        Console.WriteLine(&quot;SecondObject.OneProperty value: &quot; + myObject2.OneProperty);
        Console.WriteLine(&quot;SecondObject.OneMethod returned value: &quot; + myObject2.OneMethod(&quot;oneParameter&quot;));
    }
</code></pre>
